const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
const L = Number(input[0]);
const C = Number(input[1]);
const grid = input.slice(2, 2 + L);

let startR = -1;
let startC = -1;

for (let r = 0; r < L; r++) {
  const c = grid[r].indexOf('o');
  if (c !== -1) {
    startR = r;
    startC = c;
    break;
  }
}

const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
let previousR = startR;
let previousC = startC;
let currentR = -1;
let currentC = -1;

for (const [dr, dc] of directions) {
  const nr = startR + dr;
  const nc = startC + dc;
  if (nr >= 0 && nr < L && nc >= 0 && nc < C && grid[nr][nc] === 'H') {
    currentR = nr;
    currentC = nc;
    break;
  }
}

while (true) {
  let nextR = -1;
  let nextC = -1;

  for (const [dr, dc] of directions) {
    const nr = currentR + dr;
    const nc = currentC + dc;
    if (
      nr >= 0 && nr < L && nc >= 0 && nc < C &&
      grid[nr][nc] === 'H' &&
      (nr !== previousR || nc !== previousC)
    ) {
      nextR = nr;
      nextC = nc;
      break;
    }
  }

  if (nextR === -1) break;

  previousR = currentR;
  previousC = currentC;
  currentR = nextR;
  currentC = nextC;
}

console.log(`${currentR + 1} ${currentC + 1}`);
